commands.command:
node --input-type=module <<'NODE'
import{readFile}from'node:fs/promises';
import{validateTracker,sha256}from'./scripts/remediation/board.mjs';
const raw=await readFile('docs/remediation/evidence/W05.06/trusted-tracker-266.json');
if(sha256(raw)!=='b2c5cdbdd3d7a4c11a125b49d0e2927bfb563b0e79a05575efa48570f583d447')throw Error('trusted266 drift');
const before=JSON.parse(raw),current=JSON.parse(await readFile('docs/remediation/tracker.json'));
const startedAt=new Date().toISOString();
const result=validateTracker(current,{rootDir:process.cwd(),previousTracker:before});
console.log(JSON.stringify({startedAt,completedAt:new Date().toISOString(),from:before.journal.at(-1).seq,to:current.journal.at(-1).seq,...result}));
if(!result.ok)process.exitCode=1;
NODE
